# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "0.4.0"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v0.4.0/dedup-0.4.0-macos-arm64.tar.gz"
      sha256 "e85452fbbce9d218f23b918a6849c859483b3716402c5c109e03b7fa57942447"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v0.4.0/dedup-0.4.0-macos-x86_64.tar.gz"
      sha256 "3f108099381a7bdaeecd8ceb317c4c63dff9e9df77b348044c117886a3a64285"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v0.4.0/dedup-0.4.0-linux-x86_64.tar.gz"
    sha256 "d73f4bfa95cadd726e4306cf4d611d1c5bef59e033bc8855bafeb2b37187d037"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
